package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

/** 仅当前lease可读取固定会话上下文及任务固定用途secret；Runner不能指定任意用户/scope。 */
public class PcRunnerContextService {
    private final PcStore store;private final PcRunnerService runner;private final PcKnowledgeService knowledge;private final PcConnectionService connections;private final PcToolService tools;private final PcIdempotency idem;private final PcAccess access;private final PcArtifactService artifacts;
    public PcRunnerContextService(PcStore s,PcRunnerService r,PcKnowledgeService k,PcConnectionService c,PcToolService t,PcIdempotency i,PcAccess a,PcArtifactService ar){store=s;runner=r;knowledge=k;connections=c;tools=t;idem=i;access=a;artifacts=ar;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> context(PcRunnerPrincipal actor,Map<String,Object> input){
        PcRecord task=runner.lease(actor,input,false);Map<String,Object> p=store.data(task),result=new LinkedHashMap<>();result.put("text",p.getOrDefault("input",""));result.put("input",p.getOrDefault("input",""));result.put("mode",p.get("mode"));result.put("taskPayload",p);
        PcRecord session=store.require(PcTable.SESSION,task.getSessionId(),false);Map<String,Object> sessionData=store.data(session);long start=sessionData.get("contextStartSequence") instanceof Number n?n.longValue():0;
        long endSequence=session.getSequenceNumber();Long summaryId=null;var summaries=store.mapper.list(PcTable.CONTEXT_SUMMARY,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),"VERIFIED");for(PcRecord summary:summaries){if(summary.getKind().equals("ACTOR_SUMMARY"))continue;Map<String,Object> data=store.data(summary);long end=PcJson.number(data,"endSequence");if(end>=start&&end<=endSequence){start=end;summaryId=summary.getId();break;}}
        PcRecord activeLease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);Map<String,Object> paging=store.data(activeLease);paging.put("historyStartSequence",start);paging.put("contextEndSequence",endSequence);if(summaryId==null)paging.remove("historySummaryId");else paging.put("historySummaryId",summaryId);store.save(PcTable.TASK_LEASE,activeLease,paging);
        Map<String,Object> history=page(task,session,start,endSequence,200,false,0,paging),ledger=page(task,session,0,endSequence,200,true,0,paging);result.put("history",history.get("messages"));result.put("messages",history.get("messages"));result.put("ledgerEntries",ledger.get("entries"));result.put("historyCursor",history.get("cursor"));result.put("historySummaryOffset",history.get("summaryOffset"));result.put("historyHasMore",history.get("hasMore"));result.put("ledgerCursor",ledger.get("cursor"));result.put("ledgerHasMore",ledger.get("hasMore"));result.put("endSequence",endSequence);result.put("lastMessageSequence",endSequence);
        if(p.get("attachments") instanceof List<?> ids){List<Map<String,Object>> attachments=new ArrayList<>();for(Object id:ids)attachments.add(imageReference(Long.parseLong(String.valueOf(id)),task));result.put("attachments",attachments);}
        List<Map<String,Object>> memories=new ArrayList<>();memories.addAll(knowledge.memories(task.getOwnerId(),task.getWorkspaceId(),"PROJECT").stream().filter(m->!Set.of("DELETED","CONFLICT","REVOKED_IMPORT").contains(m.getState())).map(knowledge::entry).toList());memories.addAll(knowledge.memories(task.getOwnerId(),null,"PERSONAL").stream().filter(m->!Set.of("DELETED","CONFLICT","REVOKED_IMPORT").contains(m.getState())).map(knowledge::entry).toList());result.put("memoryEntries",memories);result.put("memories",memories);
        var plans=store.mapper.list(PcTable.PLAN,task.getWorkspaceId(),task.getOwnerId(),task.getId(),null);if(!plans.isEmpty())result.put("plan",store.view(plans.get(0)));
        PcRecord workspace=store.require(PcTable.WORKSPACE,task.getWorkspaceId(),false);Map<String,Object> workspaceView=store.view(workspace);workspaceView.put("sandboxVerified",Boolean.TRUE.equals(store.data(store.require(PcTable.RUNNER,actor.runnerId(),false)).get("sandboxVerified")));result.put("workspace",workspaceView);Map<String,Object> policy=store.view(store.mapper.findKey(PcTable.POLICY_VERSION,"workspace:"+task.getWorkspaceId(),false));Map<String,Object> wd=store.data(workspace);String day=store.clock.instant().atZone(java.time.ZoneOffset.UTC).toLocalDate().toString();long used=day.equals(wd.get("usageDay"))&&wd.get("dailyTokenUsed") instanceof Number n?n.longValue():0;policy.put("dailyRemainingTokenBudget",Math.max(0,PcJson.number(policy,"dailyTokenBudget")-used));policy.putIfAbsent("maxOutputTokens",4096);if(p.get("taskTokenBudget") instanceof Number budget)policy.put("taskTokenBudget",Math.min(PcJson.number(policy,"taskTokenBudget"),budget.longValue()));if(p.get("wechatBindingId")!=null){PcRecord binding=store.require(PcTable.WECHAT_BINDING,PcJson.number(p,"wechatBindingId"),false);Map<String,Object> bd=store.data(binding);long wxUsed=day.equals(bd.get("budgetDay"))?PcJson.number(bd,"dailyUsed"):0;policy.put("dailyRemainingTokenBudget",Math.min(PcJson.number(policy,"dailyRemainingTokenBudget"),Math.max(0,PcJson.number(bd,"dailyBudget")-wxUsed)));result.put("wechatPolicy",p.get("wechatPolicy"));}result.put("policy",policy);result.put("autoFactExtractionEnabled",!Boolean.FALSE.equals(policy.get("autoFactExtractionEnabled")));result.put("autoCompactionEnabled",!Boolean.FALSE.equals(policy.get("autoCompactionEnabled")));result.put("sessionMemoryEnabled",Boolean.TRUE.equals(policy.get("sessionMemoryEnabled")));result.put("promptTemplates",PcPromptService.forTask(store,task));result.putAll(PcProjectRuleService.forTask(store,task));
        for(var pair:Map.of("mcpConfigs",PcTable.MCP_CONFIG,"browserConfigs",PcTable.BROWSER_CONFIG).entrySet())result.put(pair.getKey(),store.mapper.list(pair.getValue(),task.getWorkspaceId(),null,null,null).stream().map(r->r.getKind().equals("BROWSER")?connections.browserConfiguration(r):connections.configuration(r)).toList());
        result.put("skillsConfigs",connections.skillsForTask(task));
        result.putAll(providerContext(actor,input));result.put("snapshots",store.mapper.list(PcTable.SNAPSHOT,task.getWorkspaceId(),task.getOwnerId(),null,null).stream().map(store::view).toList());return result;
    }
    @Transactional("paicliTransactionManager") public Map<String,Object> read(PcRunnerPrincipal actor,Map<String,Object> input,boolean ledger){PcRecord task=runner.lease(actor,input,false),session=store.require(PcTable.SESSION,task.getSessionId(),false),lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);Map<String,Object> paging=store.data(lease);long after=PcJson.number(input,"afterSequence"),end=PcJson.number(input,"endSequence"),start=ledger?0:PcJson.number(paging,"historyStartSequence");int limit=input.containsKey("limit")?(int)PcJson.number(input,"limit"):200,offset=input.containsKey("summaryOffset")?(int)PcJson.number(input,"summaryOffset"):0;if(after<start||after>end||end!=PcJson.number(paging,"contextEndSequence")||limit<1||limit>200||offset<0)throw PcException.conflict("账本分页游标或固定截止序列非法，请重新读取上下文");return page(task,session,after,end,limit,ledger,offset,paging);}
    private Map<String,Object> page(PcRecord task,PcRecord session,long after,long end,int limit,boolean ledger,int summaryOffset,Map<String,Object> binding){List<Map<String,Object>> entries=new ArrayList<>();long bytes=0,cursor=after;int offset=summaryOffset;List<Map<String,Object>> prefix=new ArrayList<>();if(!ledger&&binding.get("historySummaryId")!=null){PcRecord summary=store.require(PcTable.CONTEXT_SUMMARY,PcJson.number(binding,"historySummaryId"),false);Map<String,Object> data=store.data(summary);if(data.get("messages") instanceof List<?> list)for(Object value:list){if(!(value instanceof Map<?,?> m))throw PcException.invalid("派生摘要消息非法");Map<String,Object> typed=new LinkedHashMap<>();m.forEach((k,v)->typed.put(String.valueOf(k),v));prefix.add(llmMessage(enrichImages(typed,task)));}else prefix.add(Map.of("role","system","content",PcJson.text(data,"summary")));}if(offset>prefix.size())throw PcException.invalid("摘要分页偏移非法");
        while(offset<prefix.size()&&entries.size()<limit){Map<String,Object> value=prefix.get(offset);long size=pageBytes(value);if(!entries.isEmpty()&&bytes+size>16L*1024*1024)break;entries.add(value);bytes+=size;offset++;}boolean more=offset<prefix.size();if(!more){List<PcRecord> rows=store.mapper.messages(task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),after,end,limit+1);int consumed=0;for(PcRecord row:rows){if(!ledger&&row.getKind().equals("LEDGER_EVENT")){cursor=row.getSequenceNumber();consumed++;continue;}Map<String,Object> value=ledger?ledgerEntry(row,task,session):llmMessage(messageData(store.data(row),task));long size=pageBytes(value);if(entries.size()>=limit||(!entries.isEmpty()&&bytes+size>16L*1024*1024)){more=true;break;}entries.add(value);bytes+=size;cursor=row.getSequenceNumber();consumed++;}more=more||consumed<rows.size()||(rows.size()>=limit+1&&cursor<end);}Map<String,Object> result=new LinkedHashMap<>();result.put(ledger?"entries":"messages",entries);result.put("cursor",cursor);result.put("hasMore",more);result.put("endSequence",end);if(!ledger)result.put("summaryOffset",offset);return result;}
    private long pageBytes(Object value){long bytes=store.json.write(value).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(bytes>20L*1024*1024)throw new PcException(413,"PC_LEDGER_RECORD_TOO_LARGE","单消息超过20MB，请保留完整产物引用后重新派发，中心不截断原文");return bytes;}
    private Map<String,Object> messageData(Map<String,Object> data,PcRecord task){Map<String,Object> result=enrichImages(data,task);if(result.get("attachments") instanceof List<?> ids&&!ids.isEmpty()){List<Map<String,Object>> parts=new ArrayList<>();parts.add(Map.of("type","text","text",PcJson.text(result,"content")));for(Object id:ids){Map<String,Object> part=new LinkedHashMap<>(imageReference(Long.parseLong(String.valueOf(id)),task));part.put("type","image_artifact");parts.add(part);}result.put("contentParts",parts);}return result;}
    @Transactional("paicliTransactionManager") public Map<String,Object> providerContext(PcRunnerPrincipal actor,Map<String,Object> input){PcRecord task=runner.lease(actor,input,false);Map<String,Object> result=new LinkedHashMap<>();result.putAll(connections.providerContext(task));result.putAll(connections.embeddingContext(task));result.putAll(connections.searchContext(task));Map<String,Object> binding=new LinkedHashMap<>();for(String key:List.of("provider","model","providerConfig","modelConfig","contextWindow","embeddingConfig","searchConfig"))if(result.containsKey(key)){if(key.endsWith("Config")&&result.get(key) instanceof Map<?,?> map){Map<String,Object> fixed=new LinkedHashMap<>();for(String field:List.of("id","version","provider","modelId","baseUrl","secretRef","supportsImages","supportsThinking","supportsTools","contextWindow","providerId","searchEngine","model","transport","configHash","template","imageInput","thinking","reasoningEffort","reasoningHistory","dsml","maxOutputTokens","loraId","temperature","maxTokens"))if(map.containsKey(field))fixed.put(field,map.get(field));binding.put(key,fixed);}else binding.put(key,result.get(key));}for(String key:List.of("managedSecret","embeddingSecret","searchSecret"))if(result.get(key) instanceof Map<?,?>){Map<String,Object> grant=PcJson.object(result,key);binding.put(key,Map.of("secretRef",grant.getOrDefault("secretRef",""),"secretVersion",grant.getOrDefault("secretVersion",0)));}String hash=store.json.hash(binding);PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);Map<String,Object> data=store.data(lease);if(data.get("providerBindingHash")!=null&&!hash.equals(data.get("providerBindingHash")))throw new PcException(409,"PC_PROVIDER_FROZEN_CONFIG","任务固定模型、供应商或用途密钥版本已变化，请核对后重新提交任务");if(!data.containsKey("providerBindingHash")){data.put("providerBindingHash",hash);store.save(PcTable.TASK_LEASE,lease,data);}return result;}
    /** 凭证用途必须来自已消费的当前调用，不允许用上下文读取权限枚举工作区密钥。 */
    @Transactional("paicliTransactionManager") public Map<String,Object> mcpContext(PcRunnerPrincipal actor,Map<String,Object> input){
        PcRecord task=runner.lease(actor,input,false),call=tools.consumedTool(actor,input);Map<String,Object> callData=store.data(call);
        for(String field:List.of("taskId","leaseId","fencingToken","version"))if(!Objects.toString(callData.get(field),"").equals(Objects.toString(input.get(field),"")))throw PcException.deny("MCP凭证许可不属于当前租约attempt");
        PcRecord config=store.require(PcTable.MCP_CONFIG,PcJson.number(input,"configId"),true);if(!Objects.equals(config.getWorkspaceId(),task.getWorkspaceId()))throw PcException.deny("MCP配置不能跨工作区派发");Map<String,Object> data=store.data(config);String hash=PcJson.text(data,"configHash");long definition=connections.definition(config);
        if(!hash.matches("[a-f0-9]{64}")||!hash.equals(PcJson.text(data,"trustedHash")))throw PcException.deny("MCP配置当前hash尚未批准或信任已撤销");
        if(PcJson.number(input,"configVersion")!=definition||!hash.equals(PcJson.text(input,"configHash")))throw PcException.conflict("MCP配置定义版本已变化");
        if(call.getKind().startsWith("control__")){
            tools.consumedControl(actor,input,"MCP_START","MCP_STOP","MCP_RESTART","MCP_READ_RESOURCE","MCP_READ_PROMPT","BROWSER_CONNECT","BROWSER_DISCONNECT","BROWSER_TABS");Map<String,Object> frozen=PcJson.object(store.data(task),"arguments");
            if(call.getKind().startsWith("control__BROWSER_")){Map<String,Object> browser=PcJson.object(frozen,"config");if(!"chrome-devtools".equals(PcJson.text(data,"name"))||PcJson.number(browser,"mcpConfigId")!=config.getId()||PcJson.number(browser,"mcpConfigVersion")!=definition||!hash.equals(PcJson.text(browser,"mcpConfigHash")))throw PcException.deny("浏览器凭证不属于冻结chrome-devtools配置");}else if(PcJson.number(frozen,"configId")!=config.getId()||PcJson.number(frozen,"configVersion")!=definition||!hash.equals(PcJson.text(PcJson.object(frozen,"config"),"configHash")))throw PcException.conflict("MCP凭证不属于冻结控制配置");
        }else{
            if(!(config.getState().equals("READY")&&call.getKind().startsWith("mcp__"+PcJson.text(data,"name")+"__")||Set.of("browser_connect","browser_disconnect","browser_status").contains(call.getKind())&&"chrome-devtools".equals(PcJson.text(data,"name")))||PcJson.number(callData,"mcpConfigId")!=config.getId()||PcJson.number(callData,"mcpConfigVersion")!=definition||!hash.equals(PcJson.text(callData,"mcpConfigHash")))throw PcException.deny("MCP凭证不属于已消费工具的已批准配置");
        }
        Map<String,Object> result=new LinkedHashMap<>(connections.mcpGrant(task,config)),binding=new LinkedHashMap<>();for(String field:List.of("configId","configVersion","configHash","envSecretRefs","headerSecretRefs","secretVersions"))binding.put(field,result.get(field));
        String bindingHash=store.json.hash(binding);PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);Map<String,Object> leaseData=store.data(lease),bindings=leaseData.get("mcpBindingHashes") instanceof Map<?,?>?PcJson.object(leaseData,"mcpBindingHashes"):new LinkedHashMap<>();String id=String.valueOf(config.getId());
        if(bindings.containsKey(id)&&!bindingHash.equals(bindings.get(id)))throw new PcException(409,"PC_MCP_FROZEN_CONFIG","任务固定MCP凭证引用或版本已变化，请核对后重新提交任务");
        if(!bindings.containsKey(id)){bindings.put(id,bindingHash);leaseData.put("mcpBindingHashes",bindings);store.save(PcTable.TASK_LEASE,lease,leaseData);}
        for(String field:List.of("taskId","leaseId","fencingToken","version")){Object value=input.get(field);result.put(field,value);binding.put(field,value);}
        java.time.Instant expiry=store.clock.instant().plusSeconds(60);if(expiry.isAfter(lease.getExpiresAt()))expiry=lease.getExpiresAt();result.put("expiresAt",expiry.toString());result.put("grantHash",store.json.hash(binding));return result;
    }
    private Map<String,Object> ledgerEntry(PcRecord row,PcRecord task,PcRecord session){Map<String,Object> data=store.data(row);Map<String,Object> entry=data.get("_ledger") instanceof Map<?,?>?PcJson.object(data,"_ledger"):new LinkedHashMap<>();entry.put("schemaVersion",1);entry.put("sessionId",String.valueOf(row.getSessionId()));entry.put("sequence",row.getSequenceNumber());entry.putIfAbsent("timestamp",row.getCreatedAt().toEpochMilli());entry.putIfAbsent("event","user".equals(data.get("role"))?"USER_INPUT":"LEDGER_MESSAGE");entry.putIfAbsent("mode",store.data(session).getOrDefault("mode","REACT"));entry.putIfAbsent("actor","user".equals(data.get("role"))?String.valueOf(row.getOwnerId()):PcJson.text(data,"role"));entry.putIfAbsent("source",row.getRunnerId()==null?"CENTER_USER":"RUNNER");entry.putIfAbsent("metadata",Map.of("ownerId",String.valueOf(row.getOwnerId()),"runnerId",Objects.toString(row.getRunnerId(),"")));entry.put("message",row.getKind().equals("LEDGER_EVENT")?null:llmMessage(messageData(data,task)));return entry;}
    private Map<String,Object> enrichImages(Map<String,Object> data,PcRecord task){Map<String,Object> result=new LinkedHashMap<>(data);if(result.get("contentParts") instanceof List<?> parts){List<Object> enriched=new ArrayList<>();for(Object value:parts){if(value instanceof Map<?,?> part&&part.get("artifactId")!=null){Map<String,Object> image=new LinkedHashMap<>(imageReference(Long.parseLong(part.get("artifactId").toString()),task));image.put("type","image_artifact");enriched.add(image);}else enriched.add(value);}result.put("contentParts",enriched);}return result;}
    private Map<String,Object> imageReference(long id,PcRecord task){PcRecord artifact=store.require(PcTable.ARTIFACT,id,false);if(!Objects.equals(artifact.getWorkspaceId(),task.getWorkspaceId())||!Objects.equals(artifact.getOwnerId(),task.getOwnerId()))throw PcException.deny("图片引用不属于任务用户工作区");Map<String,Object> p=store.data(artifact);return Map.of("artifactId",String.valueOf(id),"name",p.getOrDefault("fileName","image"),"mimeType",p.getOrDefault("mimeType",p.getOrDefault("contentType","application/octet-stream")),"sha256",p.getOrDefault("sha256",artifact.getContentHash()),"size",p.getOrDefault("size",0));}
    @Transactional("paicliTransactionManager") public Map<String,Object> image(PcRunnerPrincipal actor,long artifactId,Map<String,Object> input){PcRecord task=runner.lease(actor,input,false);PcRecord artifact=store.require(PcTable.ARTIFACT,artifactId,false);if(!Objects.equals(artifact.getWorkspaceId(),task.getWorkspaceId())||!Objects.equals(artifact.getOwnerId(),task.getOwnerId()))throw PcException.deny("图片不属于当前任务用户工作区");boolean bound=Objects.equals(artifact.getSessionId(),task.getSessionId())||containsArtifact(store.data(task),artifactId);if(!bound)for(PcRecord message:store.mapper.list(PcTable.MESSAGE,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),null))if(containsArtifact(store.data(message),artifactId)){bound=true;break;}if(!bound)throw PcException.deny("图片不是该会话或任务授权的引用");return artifacts.runnerImage(artifactId,task.getWorkspaceId(),task.getOwnerId());}
    private boolean containsArtifact(Object value,long id){if(value instanceof Map<?,?> map){if(map.get("artifactId")!=null&&map.get("artifactId").toString().equals(String.valueOf(id)))return true;if(map.get("attachments") instanceof List<?> ids&&ids.stream().anyMatch(v->v.toString().equals(String.valueOf(id))))return true;for(Object v:map.values())if(containsArtifact(v,id))return true;}else if(value instanceof List<?> list)for(Object v:list)if(containsArtifact(v,id))return true;return false;}
    private Map<String,Object> llmMessage(Map<String,Object> input){Map<String,Object> out=new LinkedHashMap<>();for(String key:List.of("role","content","reasoningContent","toolCalls","toolCallId","contentParts"))if(input.containsKey(key))out.put(key,input.get(key));return out;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> memory(PcRunnerPrincipal actor,String key,Map<String,Object> input){
        PcRecord task=runner.lease(actor,input,false);String action=PcJson.text(input,"action"),scope=PcJson.text(input,"scope");boolean personal=scope.equalsIgnoreCase("global")||scope.equalsIgnoreCase("PERSONAL");Long workspace=personal?null:task.getWorkspaceId();
        if(action.equals("list"))return Map.of("entries",knowledge.memories(task.getOwnerId(),workspace,personal?"PERSONAL":"PROJECT").stream().filter(m->!m.getState().equals("DELETED")).map(knowledge::entry).toList());
        if(action.equals("write"))return tools.writeMemory(actor,key,input,knowledge);
        return idem.run("runner:"+actor.runnerId()+":memory",key,input,()->{
            if(action.equals("proposeAutomatic")){
                String fact=PcJson.text(input,"fact"),original=PcJson.text(input,"originalUserText"),actual=PcJson.text(store.data(task),"input");
                PcRecord session=store.require(PcTable.SESSION,task.getSessionId(),true);if(Boolean.TRUE.equals(store.data(session).get("externalMemoryPaused"))||fact.isBlank()||!actual.equals(original)||!actual.contains(fact))return Map.of("accepted",false,"status","REJECTED_SOURCE");
                long count=store.mapper.list(PcTable.MEMORY,workspace,task.getOwnerId(),task.getId(),null).stream().filter(r->"AUTO_USER_QUOTE".equals(PcJson.text(store.data(r),"source"))).count();if(count>=3)return Map.of("accepted",false,"status","LIMIT_REACHED");Map<String,Object> response=new LinkedHashMap<>(knowledge.memoryWrite(task.getOwnerId(),workspace,task.getSessionId(),task.getId(),fact,"AUTO_USER_QUOTE","PENDING",input));response.put("accepted","PENDING".equals(response.get("status")));return response;
            }
            String operation=PcJson.text(store.data(task),"operation");Map<String,Object> frozen=PcJson.object(store.data(task),"arguments");if(!operation.equals("MEMORY_"+action.toUpperCase(Locale.ROOT)))throw PcException.deny("记忆验证或删除必须来自明确的用户控制命令，模型不能自行执行");
            tools.consumedControl(actor,input,operation);if(!scope.equals(PcJson.text(frozen,"scope")))throw PcException.deny("记忆scope与控制指令不符");
            if(action.equals("clear")){List<PcRecord> rows=knowledge.memories(task.getOwnerId(),workspace,personal?"PERSONAL":"PROJECT");for(PcRecord row:rows){row.setState("DELETED");store.save(PcTable.MEMORY,row,store.data(row));}return Map.of("cleared",true);}
            long id=PcJson.number(input,"id");if(id!=PcJson.number(frozen,"id"))throw PcException.deny("记忆对象与用户指令不符");PcRecord row=store.require(PcTable.MEMORY,id,true);if(!Objects.equals(row.getWorkspaceId(),workspace)||(personal&&!Objects.equals(row.getOwnerId(),task.getOwnerId())))throw PcException.deny("记忆scope不属于任务用户");store.version(row,PcJson.number(input,"version"));Map<String,Object> data=store.data(row);
            if(action.equals("verify")){row.setState("VERIFIED");data.put("verifiedAt",store.clock.instant().toString());}else if(action.equals("delete"))row.setState("DELETED");else throw PcException.invalid("记忆操作非法");store.save(PcTable.MEMORY,row,data);return action.equals("delete")?Map.of("deleted",true):Map.of("entry",knowledge.entry(row));
        });
    }
    @Transactional("paicliTransactionManager")
    public Map<String,Object> review(PcRunnerPrincipal actor,Map<String,Object> input){
        PcRecord task=runner.lease(actor,input,true);var plans=store.mapper.list(PcTable.PLAN,task.getWorkspaceId(),task.getOwnerId(),task.getId(),null);
        if(task.getState().equals("CANCELLING"))return Map.of("decision","cancel","status","CANCELLING","taskId",String.valueOf(task.getId()));store.version(task,PcJson.number(input,"version"));if(!Set.of("RUNNING","WAITING_APPROVAL").contains(task.getState()))throw PcException.conflict("任务状态不允许提交新计划");if(plans.isEmpty()||(plans.get(0).getState().equals("REVISION_REQUESTED")&&input.get("steps") instanceof List<?> && !store.json.hash(input.get("steps")).equals(store.json.hash(store.data(plans.get(0)).get("steps"))))){runner.reviewedPlan(task,input);plans=store.mapper.list(PcTable.PLAN,task.getWorkspaceId(),task.getOwnerId(),task.getId(),null);}
        PcRecord plan=plans.get(0);Map<String,Object> p=store.data(plan);String decision=switch(plan.getState()){case "APPROVED"->"execute";case "REVISION_REQUESTED"->"supplement";case "CANCELLED"->"cancel";default->"pending";};
        return Map.of("planId",String.valueOf(plan.getId()),"planVersion",p.getOrDefault("definitionVersion",1),"version",plan.getVersion(),"status",plan.getState(),"decision",decision,"feedback",p.getOrDefault("feedback",""));
    }
}
